/**
 * Every scenario that TOLERATES load-shedding must also BOUND it (KS-971).
 *
 * THE GAP THIS CLOSES. `helpers/http.ts` exposes `tolerateSheddingStatuses()`, which calls
 * `http.setResponseCallback(http.expectedStatuses({min:200,max:399}, 429, 503))` so 429/503 stop
 * counting toward `http_req_failed`. That is correct and deliberate: `stress`, `spike` and
 * `scalability` deliberately overload a single host, graceful shedding IS the contract-compliant
 * response, and counting it as failure makes the error budget unmeetable (KS-195/196/198).
 *
 * But nothing then bounded HOW MUCH was shed. Failure was tolerated and the shed rate was
 * unthresholded, so a run in which the platform served almost nothing still went green. Measured
 * 2026-09-07 on four concurrent slots: `spike` shed 79.9% and `scalability` 71.1%, both `passed:
 * true`. "Spike passed" meant "the platform shed four requests in five and the survivors were
 * fast" — defensible per-metric, misleading as a verdict.
 *
 * WHY A TEST RATHER THAN JUST THE THRESHOLDS. The two halves live in different files and neither
 * points at the other: the toleration is a function call in `scenarios/*.ts`, the ceiling is a YAML
 * key in `config/scenarios.yml`. A new saturation scenario that copies an existing one picks up the
 * toleration and can easily miss the ceiling, which reintroduces exactly this defect and silently.
 * The invariant is what matters, so the invariant is what is asserted — not a hardcoded list of six
 * scenario names that the next author would have to know to update.
 */

import { readFileSync, readdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { describe, expect, it } from 'vitest';
import * as yaml from 'js-yaml';

const perfRoot = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..');

/** Marker that a scenario has opted 429/503 out of `http_req_failed`. */
const TOLERATES_SHEDDING = 'tolerateSheddingStatuses';

interface ScenarioConfig {
    readonly thresholds?: Record<string, readonly string[]>;
}

/**
 * Load the scenario definitions the runner reads.
 *
 * @returns {Record<string, ScenarioConfig>} Every scenario from `config/scenarios.yml`.
 */
function loadScenarios(): Record<string, ScenarioConfig> {
    const raw = yaml.load(readFileSync(join(perfRoot, 'config', 'scenarios.yml'), 'utf8')) as Record<string, unknown>;
    return (raw['scenarios'] ?? raw) as Record<string, ScenarioConfig>;
}

/**
 * Find the k6 scripts that opt 429/503 out of `http_req_failed`.
 *
 * @returns {string[]} Base scenario names whose script calls `tolerateSheddingStatuses()`, e.g.
 *   `spike` from `scenarios/spike.ts`.
 */
function sheddingTolerantScripts(): string[] {
    const dir = join(perfRoot, 'scenarios');
    return readdirSync(dir)
        .filter((f) => f.endsWith('.ts'))
        .filter((f) => readFileSync(join(dir, f), 'utf8').includes(`${TOLERATES_SHEDDING}(`))
        .map((f) => f.replace(/\.ts$/, ''));
}

/**
 * Pair a scenario with its `-short` sibling, which runs the same script and so inherits the same
 * shedding toleration.
 *
 * @param {string} name - Base scenario name.
 * @param {Record<string, ScenarioConfig>} scenarios - All configured scenarios.
 * @returns {string[]} `name`, plus `name-short` when that sibling exists.
 */
function withShortVariant(name: string, scenarios: Record<string, ScenarioConfig>): string[] {
    const short = `${name}-short`;
    return short in scenarios ? [name, short] : [name];
}

describe('load-shedding scenarios', () => {
    it('finds the saturation scripts that opt out of counting 429/503 as failures', () => {
        // Guards the test itself: if this returns nothing — a rename, a moved helper — every
        // assertion below would pass vacuously while asserting nothing at all.
        expect(sheddingTolerantScripts().length).toBeGreaterThan(0);
    });

    it('bounds shedding on every scenario that tolerates it', () => {
        const scenarios = loadScenarios();
        const missing: string[] = [];

        for (const script of sheddingTolerantScripts()) {
            for (const name of withShortVariant(script, scenarios)) {
                const ceiling = scenarios[name]?.thresholds?.['http_rate_limited'];
                if (ceiling === undefined || ceiling.length === 0) {
                    missing.push(name);
                }
            }
        }

        // Named rather than counted, so a failure says which scenario to fix.
        expect(missing).toEqual([]);
    });

    it('keeps the ceiling loose enough to still permit shedding', () => {
        // A saturation scenario is SUPPOSED to shed. A tight bound here (smoke's rate<0.01, say)
        // would fail every run and get removed, leaving the defect behind — the ceiling only
        // survives if it is a total-collapse detector rather than a shedding budget.
        const scenarios = loadScenarios();

        for (const script of sheddingTolerantScripts()) {
            for (const name of withShortVariant(script, scenarios)) {
                for (const rule of scenarios[name]?.thresholds?.['http_rate_limited'] ?? []) {
                    const bound = Number(/rate<([0-9.]+)/.exec(rule)?.[1] ?? NaN);
                    expect(bound).toBeGreaterThan(0.5);
                    expect(bound).toBeLessThan(1);
                }
            }
        }
    });

    it('does NOT bound shedding on load or soak, where a 429 is a real failure', () => {
        // helpers/http.ts is explicit: "Do NOT use in load/soak — at normal traffic levels a 429 IS
        // a failure." There it must count in http_req_failed, and a separate ceiling would imply
        // some shedding is acceptable at normal load. It is not.
        const scenarios = loadScenarios();

        for (const name of ['load', 'soak']) {
            expect(sheddingTolerantScripts()).not.toContain(name);
            expect(scenarios[name]?.thresholds?.['http_rate_limited']).toBeUndefined();
        }
    });
});

/**
 * Characterization test: pins the API path strings in `config/endpoints.ts`.
 *
 * The endpoint extraction must keep request URLs byte-identical, so the static
 * paths and the parameterised builders are snapshotted here. A drift in any path
 * (which would change the live request URL and its `tags.name`) fails this test.
 *
 * @module tests/unit/config/endpoints.test
 */

import { ENDPOINTS } from '../../../config/endpoints.ts';

describe('config/endpoints — path snapshot', () => {
    it('pins static paths', () => {
        expect({
            health: ENDPOINTS.health,
            login: ENDPOINTS.login,
            logout: ENDPOINTS.logout,
            usersMe: ENDPOINTS.usersMe,
            documents: ENDPOINTS.documents,
            certificationsIssue: ENDPOINTS.certificationsIssue,
            verify: ENDPOINTS.verify,
            analyticsOverview: ENDPOINTS.analyticsOverview,
        }).toEqual({
            health: '/health',
            login: '/auth/login',
            logout: '/auth/logout',
            usersMe: '/users/me',
            documents: '/documents',
            certificationsIssue: '/certifications/issue',
            verify: '/verification/verify',
            analyticsOverview: '/analytics/overview',
        });
    });

    it('builds parameterised paths', () => {
        expect(ENDPOINTS.document('doc-123')).toBe('/documents/doc-123');
        expect(ENDPOINTS.anchorsByDocument('doc-123')).toBe('/anchors/document/doc-123');
    });
});
